async function compareMaterial(id){
 const request=++comparisonRequest,entry=materialById(id);if(!entry)return;
 $('#compare-title').textContent=SWATCHES.find(m=>m.id===id)?.label||id;$('#compare-original').src=materialAsset(entry.originalAsset);$('#compare-crop').src=referenceCropAsset(id);$('#compare-note').textContent='Recorte original sem alteração de cor por luz, sombras ou exposição. Na casa, a opção Original preserva o recorte; Emendas suavizadas usa a preparação R3. A fotografia não é uma medição física de cor. Escala e rugosidade estimadas.';
 materialPreview?.dispose();$('#material-compare').showModal();$('#compare-canvas').replaceChildren();let preview=null;
 try{const canvas=document.createElement('canvas');$('#compare-canvas').appendChild(canvas);const r=new THREE.WebGLRenderer({canvas,antialias:true,preserveDrawingBuffer:true});r.setSize(340,240);r.setPixelRatio(1);r.outputColorSpace=THREE.SRGBColorSpace;r.toneMapping=THREE.NoToneMapping;const sc=new THREE.Scene();sc.background=new THREE.Color('#eceeeb');const c=new THREE.OrthographicCamera(-1.3,1.3,.92,-.92,.1,10);c.position.set(0,0,3);const material=lib.create(id,'#ddd','comparison',{mode:'source',unlit:true}),g=new THREE.PlaneGeometry(1,1),m=new THREE.Mesh(g,material);sc.add(m);let ownedMap=null;
  preview={disposed:false,dispose(){if(this.disposed)return;this.disposed=true;ownedMap?.dispose();lib.release(material);g.dispose();r.dispose();r.forceContextLoss();}};materialPreview=preview;
  const status=await lib.ready(material.userData.lease);if(preview.disposed||materialPreview!==preview||request!==comparisonRequest)return;if(status.failures.length)throw new Error('Recorte indisponível');
  if(material.map){ownedMap=material.map.clone();ownedMap.repeat.set(1,1);ownedMap.needsUpdate=true;material.map=ownedMap;const aspect=ownedMap.image.width/ownedMap.image.height,width=Math.min(2.3,1.6*aspect);m.scale.set(width,width/aspect,1);}else m.scale.set(2.2,1.4,1);r.render(sc,c);
 }catch{preview?.dispose();if(request!==comparisonRequest||!$('#material-compare').open)return;$('#compare-canvas').textContent='Comparação 3D indisponível. Os recortes originais continuam disponíveis.';}
}

async function snapshotData(configuration=S){if(!stage||contextLost)return null;const configSignature=JSON.stringify(configuration),visualSignature=JSON.stringify({...V,processProgress,roomFocus,fittingsOpen,interactionRevision});const status=await lib.ready();if(!stage||contextLost||stage.renderer.getContext().isContextLost())throw new Error('A ligação gráfica foi interrompida. Tente novamente após recuperar o 3D.');if(status?.failures?.length)throw new Error('Uma textura não carregou. Use Tentar texturas antes de guardar a imagem.');if(JSON.stringify(S)!==configSignature||JSON.stringify({...V,processProgress,roomFocus,fittingsOpen,interactionRevision})!==visualSignature)throw new Error('A configuração mudou durante a captura. Tente novamente.');stage.render();return stage.renderer.domElement.toDataURL('image/png');}
function download(content,name,type){const u=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);}
async function showSummary(){if(summaryBusy)return;stopAnimation();summaryBusy=true;let configuration={...S},thumb=null,warning='';try{try{thumb=await snapshotData(configuration);}catch(error){configuration={...S};warning='Imagem indisponível: '+error.message;notify(warning);}summaryConfiguration=Object.freeze({...configuration});summaryImage=thumb;$('#summary-content').innerHTML=summaryMarkup(configuration,{image:thumb,plan:planSVG(configuration,{compact:true}),warning});$('#summary-content .summary-commercial a').href=quoteLink(configuration);if(!$('#summary').open)$('#summary').showModal();}finally{summaryBusy=false;}}
async function rasterSVG(svg){const blob=new Blob([svg],{type:'image/svg+xml'}),url=URL.createObjectURL(blob);try{const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url;});const canvas=document.createElement('canvas');canvas.width=1140;canvas.height=1770;const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/png');}finally{URL.revokeObjectURL(url);}}
async function exportPDF(){const configuration={...(summaryConfiguration||S)},button=$('#print-config');button.disabled=true;const old=button.textContent;button.textContent='A preparar PDF…';try{const image=summaryConfiguration?summaryImage:await snapshotData(configuration),planImage=await rasterSVG(planSVG(configuration));const bytes=await createPortfolioPDF(configuration,{image,planImage});download(bytes,'green-village-72-'+configuration.layout+'-'+configurationReference(configuration)+'.pdf','application/pdf');notify('PDF de quatro páginas com materiais, configuração e planta criado.');}catch(e){console.error(e);notify('Não foi possível criar o PDF: '+e.message);}finally{button.disabled=false;button.textContent=old;}}
